      "overt_motivation": "将南方货物运到北方高价卖出",
      "covert_motivation": "通过这场流浪婚礼完成对沈芸的承诺",
      "secret_fear": "无法给沈芸安稳的生活，最终像货物一样被时代抛弃",
      "misperception_of_other": "以为沈芸只想要安稳，不敢接受他的动荡",
      "hidden_connection": "两人都是被时代洪流冲刷的边缘人"
    },
    {
      "name": "沈芸",
      "role": "deuteragonist",
      "identity": "国营厂下岗女工",
      "traits": [
        "坚韧",
        "内敛",
        "缺乏安全感",
        "勇敢"
      ],
      "overt_motivation": "赚取押货费维持生计",
      "covert_motivation": "寻找漂泊中的安全感，确认陈锋的心意",
      "secret_fear": "再次被抛弃，成为他人的累赘",
      "misperception_of_other": "以为陈锋只是雇佣她，不知道枕巾的含义",
      "hidden_connection": "在摩托车后座的七天七夜中建立了生死与共的默契"
    }
  ],
  "supporting_characters": [
    {
      "name": "老黑",
      "function": "阻碍",
      "identity": "路霸/竞争对手",
      "description": "象征路途凶险和商业残酷的具象化"
    }
  ],
  "relationship_dynamics": "从雇佣关系的伪装开始，在封闭的摩托车空间和风雨中，通过枕巾这一媒介，逐渐剥离防备，演变为共谋与深情，最终在商业失败中达成灵魂的结合。"
}","path":"characters.json"},{"content":"{
  "act_one": {
    "description": "启程与伪装。建立摩托车作为移动封闭空间的基础，引入枕巾作为核心物件。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "风雨中的金属茧",
        "core_event": "陈锋雇佣沈芸出发，暴雨中停车买红丝巾。",
        "emotional_tone": "压抑中透着一丝温情",
        "key_scenes": [
          "摩托车在暴雨中穿行",
          "陈锋把红丝巾系在沈芸脖子上"
        ]
      },
      {
        "chapter_number": 2,
        "chapter_title": "第一对鸳鸯",
        "core_event": "经过第一个县城，陈锋买下第一对枕巾，放入边斗。",
        "emotional_tone": "疑惑与试探",
        "key_scenes": [
          "供销社买枕巾",
          "沈芸看着边斗里的枕巾发呆"
        ]
      }
    ],
    "turning_point": "沈芸发现陈锋买枕巾并非为了倒卖，而是某种仪式。"
  },
  "act_two": {
    "description": "旅途与发酵。冲突升级，外部环境恶劣与内部情感升温形成对比。",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "路霸与心跳",
        "core_event": "遭遇老黑劫道，两人配合逃脱，生死时刻手紧握在一起。",
        "emotional_tone": "紧张刺激",
        "key_scenes": [
          "摩托车狂飙逃离",
          "沈芸紧抱陈锋腰际"
        ]
      },
      {
        "chapter_number": 4,
        "chapter_title": "地图上的秘密",
        "core_event": "沈芸在地图经过的城市画心，边斗被枕巾填满。",
        "emotional_tone": "甜蜜与酸涩",
        "key_scenes": [
          "旅馆昏暗灯光下看地图",
          "边斗几乎塞不下货物"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "一万张婚床",
        "core_event": "桥洞避雨，陈锋铺开所有枕巾，两人在“婚床”上过夜。",
        "emotional_tone": "浪漫至极",
        "key_scenes": [
          "桥洞下的枕巾海",
          "陈锋半开玩笑的誓言"
        ]
      }
    ],
    "turning_point": "到达北方目的地，发现市场崩盘，货物滞销。"
  },
  "act_three": {
    "description": "破碎与新生。商业冒险失败，但情感冒险成功。",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "赌局揭晓",
        "core_event": "陈锋坦白流浪婚礼的真相，因赔本要履行“人归摩托”的诺言（离开）。",
        "emotional_tone": "绝望与悲壮",
        "key_scenes": [
          "雪地里的摩托车",
          "陈锋颓废的背影"
        ]
      },
      {
        "chapter_number": 7,
        "chapter_title": "去深圳的车票",
        "core_event": "沈芸卖掉摩托车，买了两张去深圳的车票，拉起陈锋的手。",
        "emotional_tone": "坚定与新生",
        "key_scenes": [
          "交易市场卖车",
          "火车站台的拥抱"
        ]
      }
    ]
  }
}","path":"outline.json"}]}

